const crypto = require('crypto');
const accessKey = 'yCrnfHeNp7sKC5h3';
const secretKey = 'Em2sPDj0VaRGvnnY';
const baseUrl = 'https://metersphere.devops.moego.pet';
const timestamp = Date.now();
const uuid = crypto.randomUUID();
const comboxKey = `${accessKey}|${uuid}|${timestamp}`;
const key = Buffer.from(secretKey.slice(0, 16), 'utf-8');
const iv = Buffer.from(accessKey.slice(0, 16), 'utf-8');
const cipher = crypto.createCipheriv('aes-128-cbc', key, iv);
let encrypted = cipher.update(comboxKey, 'utf-8', 'base64');
encrypted += cipher.final('base64');
const input = $input.first().json;
const projectId = '20a78db9-19aa-11ee-a261-5a66b98c4036';
const page = input.page || 1;
const pageSize = input.page_size || 20;
return [{ json: { baseUrl, page, pageSize, body: { projectId }, headers: { 'Content-Type': 'application/json', 'ACCEPT': 'application/json', 'accessKey': accessKey, 'signature': encrypted } } }];

const response = $input.first().json;
if (!response.success) throw new Error(`MeterSphere API error: ${response.message}`);
const data = response.data || {};
const reviews = (data.listObject || []).map(r => ({ id: r.id, name: r.name, status: r.status, creator: r.creatorName || r.creator, pass_rate: r.passRate, case_count: r.caseCount, reviewers: (r.reviewers || []).map(u => u.name).join(', '), end_time: r.endTime ? new Date(r.endTime).toISOString() : null, create_time: r.createTime ? new Date(r.createTime).toISOString() : null }));
return [{ json: { reviews, total: data.itemCount || 0, page_count: data.pageCount || 0 } }];
